pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposits, uint256 extraEth) public {
        // Bound to reasonable ranges to avoid overflow and keep domain wide
        deposits = bound(deposits, 0, 100);
        extraEth = bound(extraEth, 0, 100 ether);

        // Owner needs funds to send
        address deployer = address(this);
        vm.deal(deployer, deposits + extraEth + 1 ether);

        // Make multiple deposits to increments depositsCount
        for (uint256 i = 0; i < deposits; i++) {
            vm.prank(deployer);
            (bool sent, ) = address(c).call{value: 1 wei}("");
            require(sent, "deposit failed");
        }

        // Add extra ether without incrementing depositsCount (direct transfer)
        if (extraEth > 0) {
            vm.prank(deployer);
            (bool sent, ) = address(c).call{value: extraEth}("");
            require(sent, "extra deposit failed");
        }

        uint256 balanceBefore = address(c).balance;
        uint256 countBefore = c.depositsCount();

        // Owner withdraws all
        vm.prank(deployer);
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;
        uint256 countAfter = c.depositsCount();

        // General rule: After withdrawAll, all ether is withdrawn, so
        // the remaining balance must be zero, while depositsCount stays unchanged.
        // balanceAfter == 0 and countAfter == countBefore.
        // Bug: withdrawAll transfers 0, so balanceAfter > 0 if extraEth > 0 or deposits > 0.
        assertTrue(balanceAfter == 0 && countAfter == countBefore);
    }
}

