pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        address owner = c.owner();
        vm.deal(address(c), amount + 1 ether);
        uint256 contractBefore = address(c).balance;
        uint256 ownerBefore = owner.balance;

        vm.prank(owner);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        uint256 contractAfter = address(c).balance;
        uint256 ownerAfter = owner.balance;

        if (ok) {
            assertTrue(contractBefore - contractAfter == amount && ownerAfter - ownerBefore == amount);
        } else {
            assertTrue(contractAfter == contractBefore && ownerAfter == ownerBefore);
        }
    }
}

