pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 preBalance) public {
        // Restrict to reasonable bounds to avoid overflow and ensure sufficient funding
        amount = bound(amount, 1, type(uint128).max);
        preBalance = bound(preBalance, amount, type(uint128).max);

        // Set up the contract with some balance
        address owner = c.owner();
        vm.deal(owner, preBalance);
        vm.prank(owner);
        (bool sent,) = address(c).call{value: preBalance}("");
        require(sent, "funding failed");

        uint256 balanceBefore = address(c).balance;

        // Execute withdraw as the owner
        vm.prank(owner);
        c.withdraw(amount);

        uint256 balanceAfter = address(c).balance;

        // The general rule: balance after withdrawal equals balance before minus withdrawn amount
        // This holds for the reference contract (withdrawal happens), but fails for the mutant (no withdrawal occurs)
        assertTrue(balanceAfter == balanceBefore - amount);
    }
}

